:root {
    --color-primary: #111827;
    --color-primary-light: #374151;
    --color-accent: #2563eb;
    --color-accent-hover: #1d4ed8;
    --color-danger: #ef4444;
    --color-bg: #f9fafb;
    --color-surface: #ffffff;
    --color-text: #1f2937;
    --color-text-muted: #6b7280;
    --color-border: #e5e7eb;

    --font-family: system-ui, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;

    --spacing-1: 0.25rem;
    --spacing-2: 0.5rem;
    --spacing-3: 0.75rem;
    --spacing-4: 1rem;
    --spacing-6: 1.5rem;
    --spacing-8: 2rem;
    --spacing-12: 3rem;
    --spacing-16: 4rem;

    --radius-md: 0.375rem;
    --radius-lg: 0.5rem;

    --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: var(--font-family);
    color: var(--color-text);
    background-color: var(--color-bg);
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
}

img {
    max-width: 100%;
    height: auto;
    display: block;
}

a {
    color: inherit;
    text-decoration: none;
    transition: color 0.2s ease;
}

ul {
    list-style: none;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-4);
}

.text-center {
    text-align: center;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

/* Accessibility Focus States */
a:focus-visible,
button:focus-visible,
input:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

/* Skip link for accessibility */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--color-accent);
    color: white;
    padding: 8px var(--spacing-4);
    z-index: 100;
    transition: top 0.2s;
    font-weight: bold;
}

.skip-link:focus {
    top: 0;
}

/* Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: var(--spacing-3) var(--spacing-6);
    border-radius: var(--radius-md);
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s ease;
    border: 1px solid transparent;
}

.btn-primary {
    background-color: var(--color-primary);
    color: white;
}

.btn-primary:hover {
    background-color: var(--color-primary-light);
}

.btn-secondary {
    background-color: var(--color-surface);
    color: var(--color-primary);
    border-color: var(--color-border);
}

.btn-secondary:hover {
    background-color: var(--color-bg);
    border-color: #d1d5db;
}

/* Header */
.site-header {
    background-color: var(--color-surface);
    border-bottom: 1px solid var(--color-border);
    position: sticky;
    top: 0;
    z-index: 50;
    box-shadow: var(--shadow-sm);
}

.header-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: var(--spacing-4);
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.logo {
    font-size: 1.5rem;
    font-weight: 800;
    letter-spacing: -0.025em;
    color: var(--color-primary);
}

.main-nav ul {
    display: flex;
    gap: var(--spacing-6);
}

.main-nav a {
    font-weight: 500;
    color: var(--color-text-muted);
}

.main-nav a:hover,
.main-nav a:focus {
    color: var(--color-primary);
}

.header-actions {
    display: flex;
    align-items: center;
    gap: var(--spacing-6);
}

.search-form {
    display: flex;
    align-items: center;
}

.search-form input {
    padding: var(--spacing-2) var(--spacing-3);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-md) 0 0 var(--radius-md);
    font-family: inherit;
    width: 200px;
}

.search-form button {
    padding: var(--spacing-2) var(--spacing-3);
    background-color: var(--color-bg);
    border: 1px solid var(--color-border);
    border-left: none;
    border-radius: 0 var(--radius-md) var(--radius-md) 0;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--color-text-muted);
}

.search-form button:hover {
    background-color: #e5e7eb;
    color: var(--color-primary);
}

.cart-button {
    background: none;
    border: none;
    cursor: pointer;
    display: flex;
    align-items: center;
    position: relative;
    color: var(--color-primary);
    padding: var(--spacing-1);
    transition: transform 0.2s ease;
}

.cart-count {
    position: absolute;
    top: -5px;
    right: -10px;
    background-color: var(--color-accent);
    color: white;
    font-size: 0.75rem;
    padding: 0.125rem 0.375rem;
    border-radius: 9999px;
    font-weight: 700;
    min-width: 20px;
    text-align: center;
}

/* Hero */
.hero {
    background-image: linear-gradient(rgba(0, 0, 0, 0.4), rgba(0, 0, 0, 0.5)), url('https://images.unsplash.com/photo-1441984904996-e0b6ba687e04?w=1600&q=80');
    background-size: cover;
    background-position: center;
    color: white;
    padding: var(--spacing-16) var(--spacing-4);
    text-align: center;
    min-height: 550px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.hero-content {
    max-width: 700px;
}

.hero h1 {
    font-size: 3.5rem;
    font-weight: 800;
    margin-bottom: var(--spacing-4);
    line-height: 1.1;
}

.hero p {
    font-size: 1.25rem;
    margin-bottom: var(--spacing-8);
    opacity: 0.9;
}

/* Sections */
section {
    padding: var(--spacing-16) 0;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    margin-bottom: var(--spacing-8);
    border-bottom: 2px solid var(--color-border);
    padding-bottom: var(--spacing-2);
}

section h2 {
    font-size: 2rem;
    color: var(--color-primary);
}

.editorial h2 {
    margin-bottom: var(--spacing-8);
    border-bottom: none;
}

.view-all {
    color: var(--color-accent);
    font-weight: 600;
}

.view-all:hover {
    text-decoration: underline;
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: var(--spacing-8);
}

.product-card {
    background-color: var(--color-surface);
    border-radius: var(--radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-sm);
    transition: box-shadow 0.3s ease, transform 0.3s ease;
    display: flex;
    flex-direction: column;
    border: 1px solid var(--color-border);
}

.product-card:hover {
    box-shadow: var(--shadow-lg);
    transform: translateY(-4px);
}

.product-image-wrapper {
    position: relative;
    aspect-ratio: 4/5;
    overflow: hidden;
    background-color: var(--color-bg);
}

.product-image-wrapper img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.product-card:hover .product-image-wrapper img {
    transform: scale(1.05);
}

.product-badge {
    position: absolute;
    top: var(--spacing-3);
    left: var(--spacing-3);
    background-color: var(--color-danger);
    color: white;
    padding: 0.25rem 0.5rem;
    font-size: 0.75rem;
    font-weight: 700;
    border-radius: var(--radius-md);
    z-index: 10;
}

.product-info {
    padding: var(--spacing-4);
    flex-grow: 1;
    display: flex;
    flex-direction: column;
}

.product-title {
    font-size: 1.125rem;
    font-weight: 600;
    margin-bottom: var(--spacing-2);
    color: var(--color-primary);
}

.product-price {
    font-weight: 700;
    color: var(--color-text);
    margin-bottom: var(--spacing-4);
    font-size: 1.125rem;
}

.product-price del {
    color: var(--color-text-muted);
    font-weight: 400;
    margin-left: var(--spacing-2);
    font-size: 0.875rem;
}

.add-to-cart {
    margin-top: auto;
    width: 100%;
}

/* Editorial */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: var(--spacing-8);
}

.editorial-card {
    background-color: var(--color-surface);
    border-radius: var(--radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-md);
    transition: transform 0.3s ease;
}

.editorial-card:hover {
    transform: translateY(-4px);
}

.editorial-card img {
    width: 100%;
    height: 350px;
    object-fit: cover;
}

.editorial-content {
    padding: var(--spacing-6);
}

.editorial-content h3 {
    font-size: 1.5rem;
    margin-bottom: var(--spacing-3);
    color: var(--color-primary);
}

.editorial-content p {
    color: var(--color-text-muted);
    margin-bottom: var(--spacing-4);
    font-size: 1.05rem;
}

.read-more {
    color: var(--color-accent);
    font-weight: 600;
    display: inline-flex;
    align-items: center;
    gap: var(--spacing-1);
}

.read-more:hover {
    color: var(--color-accent-hover);
    text-decoration: underline;
}

/* Footer */
.site-footer {
    background-color: var(--color-primary);
    color: white;
    padding-top: var(--spacing-16);
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-8);
    margin-bottom: var(--spacing-12);
}

.footer-col h3 {
    font-size: 1.125rem;
    margin-bottom: var(--spacing-4);
    color: white;
}

.footer-col p {
    color: #9ca3af;
}

.footer-col ul {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-2);
}

.footer-col a {
    color: #9ca3af;
}

.footer-col a:hover {
    color: white;
}

.newsletter-desc {
    margin-bottom: var(--spacing-4);
}

.newsletter-form {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-2);
}

.newsletter-form input {
    padding: var(--spacing-3);
    border-radius: var(--radius-md);
    border: none;
    font-family: inherit;
}

.newsletter-form button {
    justify-content: center;
}

.footer-bottom {
    border-top: 1px solid var(--color-primary-light);
    padding: var(--spacing-6) 0;
    text-align: center;
    color: #9ca3af;
}

/* Responsive */
@media (max-width: 768px) {
    .header-container {
        flex-direction: column;
        gap: var(--spacing-4);
        padding: var(--spacing-4);
    }

    .header-actions {
        width: 100%;
        justify-content: space-between;
    }

    .search-form input {
        width: 100%;
    }

    .main-nav {
        width: 100%;
        overflow-x: auto;
        padding-bottom: var(--spacing-2);
    }

    .main-nav ul {
        flex-wrap: nowrap;
        justify-content: flex-start;
        min-width: max-content;
    }

    .hero h1 {
        font-size: 2.5rem;
    }

    .section-header {
        flex-direction: column;
        gap: var(--spacing-2);
        align-items: flex-start;
    }
}
