const formatCurrency = (amount) => {
    return new Intl.NumberFormat('en-US', {
        style: 'currency',
        currency: 'USD'
    }).format(amount);
};

// Create product card HTML
const createProductCard = (product) => {
    const isDeal = product.deal && product.salePrice;
    const priceHtml = isDeal 
        ? `<div class="product-price">
             <span class="sr-only">Sale price</span>
             ${formatCurrency(product.salePrice)}
             <del><span class="sr-only">Original price</span>${formatCurrency(product.price)}</del>
           </div>`
        : `<div class="product-price">
             <span class="sr-only">Price</span>
             ${formatCurrency(product.price)}
           </div>`;

    const badgeHtml = isDeal ? `<span class="product-badge">SALE</span>` : '';

    return `
        <article class="product-card">
            <div class="product-image-wrapper">
                ${badgeHtml}
                <img src="${product.image}" alt="${product.title}" loading="lazy">
            </div>
            <div class="product-info">
                <h3 class="product-title">${product.title}</h3>
                ${priceHtml}
                <button class="btn btn-secondary add-to-cart" data-id="${product.id}" aria-label="Add ${product.title} to cart">
                    Add to Cart
                </button>
            </div>
        </article>
    `;
};

