document.addEventListener('DOMContentLoaded', () => {
    // Render Featured Products
    const featuredGrid = document.getElementById('featured-grid');
    if (featuredGrid) {
        const featuredHtml = products
            .filter(p => p.featured)
            .map(createProductCard)
            .join('');
        featuredGrid.innerHTML = featuredHtml;
    }

    // Render Deals
    const dealsGrid = document.getElementById('deals-grid');
    if (dealsGrid) {
        const dealsHtml = products
            .filter(p => p.deal)
            .map(createProductCard)
            .join('');
        dealsGrid.innerHTML = dealsHtml;
    }

    // Shopping Cart Logic
    let cartCount = 0;
    const cartCountElement = document.querySelector('.cart-count');
    const cartButton = document.querySelector('.cart-button');

    document.addEventListener('click', (e) => {
        if (e.target.classList.contains('add-to-cart')) {
            cartCount++;
            cartCountElement.textContent = cartCount;

            // Update aria-label for accessibility
            cartButton.setAttribute('aria-label', `Shopping Cart, ${cartCount} item${cartCount !== 1 ? 's' : ''}`);

            // Simple animation
            cartButton.style.transform = 'scale(1.1)';
            setTimeout(() => {
                cartButton.style.transform = 'scale(1)';
            }, 150);
        }
    });

    // Search form prevent default for demo
    const searchForm = document.querySelector('.search-form');
    if(searchForm) {
        searchForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const input = document.getElementById('search-input').value;
            if(input) {
                console.log(`Searching for: ${input}`);
                // In a real app, you would submit to a search endpoint
                document.getElementById('search-input').value = '';
            }
        });
    }

    // Newsletter form prevent default for demo
    const newsletterForm = document.querySelector('.newsletter-form');
    if(newsletterForm) {
        newsletterForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const btn = newsletterForm.querySelector('button');
            const originalText = btn.textContent;
            btn.textContent = 'Subscribed!';
            btn.classList.remove('btn-secondary');
            btn.classList.add('btn-primary');

            setTimeout(() => {
                btn.textContent = originalText;
                btn.classList.add('btn-secondary');
                btn.classList.remove('btn-primary');
                newsletterForm.reset();
            }, 3000);
        });
    }
});

